content.text:
            case 0x16:
            case 0x17:
                out.v(maximum);
                break;
            case 0x11:
            case 0x15:
                out.v(id);
                out.v(maximum);
                break;
            case 0x18:
                out.v(sequence);
                out.v(retirePriorTo);
                out.u8(data.length);
                out.bytes(data);
                out.bytes(token);
                break;
            case 0x19:
                out.v(sequence);
                break;
            case 0x1a:
            case 0x1b:
                out.bytes(data);
                break;
            case 0x1c:
                out.v(error);
                out.v(value);
                out.v(data.length);
                out.bytes(data);
                break;
            case 0x1d:
                out.v(error);
                out.v(data.length);
                out.bytes(data);
                break;
            case 0x30:
                out.bytes(data);
                break;
            case 0x31:
                out.v(length);
                out.bytes(data);
                break;
            default:
                throw new IllegalStateException("unserializable frame type " + type);
        }
    }
}

